type TextAreaId = 'biography' | 'discussion-text' | 'message-text' | 'notes' | 'share-tip-text';

export type JournalElement<I extends string> = I extends ButtonId
  ? HTMLButtonElement
  : I extends DetailsId
    ? HTMLDetailsElement
    : I extends DialogId
      ? HTMLDialogElement
      : I extends FormId
        ? HTMLFormElement
        : I extends ImageId
          ? HTMLImageElement
          : I extends InputId
            ? HTMLInputElement
            : I extends SelectId
              ? HTMLSelectElement
              : I extends TextAreaId
                ? HTMLTextAreaElement
                : HTMLElement;
